-- Base fiscal de produtos (NFC-e) — semeada do FCerta. ICMS/CEST/CFOP/origem NULL p/ contador validar.
-- Idempotente. cliente_id da farmacia Magis-TAO.

create table if not exists fiscal_produtos (
  id uuid primary key default gen_random_uuid(),
  cliente_id uuid not null, codigo_fc text not null, descricao text, grupo text,
  ncm text, cest text, gtin text, origem text, cst_icms text, csosn text,
  aliquota_icms numeric, cfop_venda text, cst_pis text, cst_cofins text,
  ind_iss boolean default false, icms_cod_fcerta text, revisado_contador boolean default false,
  obs text, criado_em timestamptz default now(), atualizado_em timestamptz default now(),
  unique (cliente_id, codigo_fc)
);
create index if not exists idx_fiscal_produtos_cli on fiscal_produtos (cliente_id);

on conflict (cliente_id, codigo_fc) do update set ncm=excluded.ncm, cst_pis=excluded.cst_pis, cst_cofins=excluded.cst_cofins, icms_cod_fcerta=excluded.icms_cod_fcerta, atualizado_em=now();
